    convertirATiempo: function convertirATiempo(horaDate) {
      // Asegurarse de que sea un objeto Date válido
      if (horaDate instanceof Date && !isNaN(horaDate)) {
        return {
          hours: horaDate.getHours(),
          // Extrae horas
          minutes: horaDate.getMinutes(),
          // Extrae minutos
          seconds: horaDate.getSeconds() // Extrae segundos (si lo necesitas)
        };
      } else {
        console.error('El valor proporcionado no es un objeto Date válido.');
        return null;
      }
    },
    calcularDiferencia: function calcularDiferencia(horaInicio, horaFin) {
      var inicio = this.convertirATiempo(horaInicio); // { hours, minutes, seconds }
      var fin = this.convertirATiempo(horaFin); // { hours, minutes, seconds }

      if (!inicio || !fin) {
        console.error('No se pudieron obtener las horas correctamente.');
        return null;
      }

      // Convertir ambas horas a segundos totales para mayor precisión
      var segundosInicio = inicio.hours * 3600 + inicio.minutes * 60 + inicio.seconds;
      var segundosFin = fin.hours * 3600 + fin.minutes * 60 + fin.seconds;

      // Calcular diferencia en segundos
      var diferenciaSegundos = segundosFin - segundosInicio;

      // Si la diferencia es negativa (fin es antes que inicio), ajustamos para el siguiente día
      if (diferenciaSegundos < 0) {
        diferenciaSegundos += 24 * 3600; // Añadir un día en segundos
      }

      // Convertir de nuevo a horas, minutos y segundos
      var horasDiferencia = Math.floor(diferenciaSegundos / 3600);
      var minutosDiferencia = Math.floor(diferenciaSegundos % 3600 / 60);
      var segundosDiferencia = diferenciaSegundos % 60;

      // Convertir los minutos a decimales y sumarlos a las horas
      var horasConDecimales = horasDiferencia + minutosDiferencia / 60;

      // Redondear los segundos para evitar errores en la representación
      var horasTotales = Math.round(horasConDecimales * 100) / 100;
      this.horas_calculadas = horasTotales;
      return {
        horas: horasTotales,
        minutos: minutosDiferencia,
        segundos: segundosDiferencia
      };
    },
